/usr/bin/bash -lc "ls -la predictions/; if [ -f state.json ]; then sed -n '1,240p' state.json; else echo 'state.json: ABSENT'; fi
python - <<'PY'
import csv, ast, json, collections, os
with open('market.csv', newline='') as f:
    rows=list(csv.DictReader(f))
active=[r for r in rows if r['is_resolved'].lower()"'!='"'true']
resolved=[r for r in rows if r['is_resolved'].lower()=='true']
covered=[r for r in active if r['my_prediction'].strip() not in ('','None','null','nan')]
print(json.dumps({
 'rows':len(rows),'active':len(active),'resolved':len(resolved),'covered':len(covered),
 'prediction_dates':dict(collections.Counter(r['my_prediction_date'] for r in active)),
 'resolution_dates':dict(collections.Counter(r['resolution_date'] for r in active).most_common(12)),
}, indent=2))
print('resolved records:')
for r in resolved: print(r['qid'],r['title'],r['ground_truth'])
base=json.load(open('memory/baseline_forecasts.json'))
def parse(x):
  try:return ast.literal_eval(x)
  except:return None
changed=[]; missing=[]
for r in active:
  q=r['qid']; p=parse(r['my_prediction'])
  if q not in base: missing.append(('base',q))
  elif p"'!=base[q]: changed.append((q,p,base[q]))
print('"'base entries',len(base),'missing',missing[:10], 'market-vs-base changed',len(changed))
for x in changed[:30]: print(x)
PY"

