import re
p='/tmp/mar28_rank.txt'
blocks=open(p).read().strip().split('\\n\\n')
for b in blocks:
    ls=b.splitlines()
    if not ls: continue
    m=re.match(r'(\\d+)\\|(["'^|]+)'"\\|(.*)',ls[0])
    vals=[]
    for x in ls[1:]:
      sm=re.match(r'\\s*([0-9.]+)\\|(["'^|]+)'"\\|(.*)',x)
      if sm: vals.append((float(sm.group(1)),sm.group(2),sm.group(3)))
    if m and vals and vals[0][0]>=55:
      print(f'{m.group(1)} {m.group(2)} {vals[0][0]:.1f} :: {m.group(3)}')
      for v in vals[:3]: print(f'  {v[0]:.1f} {v[1]} {v[2]}')
PY"

