for b in open('/tmp/mar28_rank.txt').read().strip().split('\\n\\n'):
 ls=b.splitlines(); m=re.match(r'(\\d+)\\|(["'^|]+)'"\\|(.*)',ls[0]) if ls else None
 if not m or len(ls)<2: continue
 sm=re.match(r'\\s*([0-9.]+)\\|(["'^|]+)'"\\|(.*)',ls[1])
 if sm and 30<=float(sm.group(1))<45 and sm.group(2)=='2026-03-28':
  q=m.group(2); r=rows[q]
  if r['resolution_date'] <= '2026-04-30':
   print(f\"{q}\\t{r['resolution_date']}\\t{float(sm.group(1)):.1f}\\t{m.group(3)}\\t{sm.group(3)}\\t{r['my_prediction']}\")
PY"

